import React, { useEffect } from "react";
import { useToast, addToRemoveQueue } from "../../hooks/use-toast";
import { X } from "lucide-react";

export function Toaster() {
  const { toasts, dismiss } = useToast();

  return (
    <div className="fixed bottom-4 right-4 z-50 flex flex-col gap-2 w-full max-w-sm pointer-events-none">
      {toasts.map((t) => (
        <Toast key={t.id} toast={t} onDismiss={() => dismiss(t.id)} />
      ))}
    </div>
  );
}

function Toast({ toast, onDismiss }) {
  useEffect(() => {
    if (toast.open) {
      addToRemoveQueue(toast.id);
      const timer = setTimeout(onDismiss, 4000);
      return () => clearTimeout(timer);
    }
  }, [toast.open, toast.id, onDismiss]);

  if (!toast.open) return null;

  return (
    <div className="pointer-events-auto flex items-start gap-3 rounded-xl border border-slate-200 bg-white p-4 shadow-lg animate-in slide-in-from-bottom-2">
      <div className="flex-1">
        {toast.title && (
          <div className="text-sm font-semibold text-slate-900">{toast.title}</div>
        )}
        {toast.description && (
          <div className="text-sm text-slate-500 mt-0.5">{toast.description}</div>
        )}
      </div>
      <button
        onClick={onDismiss}
        className="text-slate-400 hover:text-slate-600 shrink-0"
      >
        <X className="w-4 h-4" />
      </button>
    </div>
  );
}
